import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice creates an invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Printed flyer A4 (each)');
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects non-existent date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects missing date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 3.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLines = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), originalLines);
});

test('createInvoice returns a copy of lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  r.value.lines[0].qty = 999;
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r2.value.lines[0].qty, 5);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles quantity of 1', () => {
  const line = { qty: 1, unitPrice: 1500 };
  assert.equal(lineTotal(line), 1500);
});

test('invoiceTotals calculates subtotal from single line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals calculates subtotal from multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 5 * 8500 + 3 * 9500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with standard tier and VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'ICON-SET', qty: 50 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('addLine adds a new line to the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
});

test('addLine increases qty for existing SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 8);
});

test('addLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const originalLength = r1.value.lines.length;
  addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r1.value.lines.length, originalLength);
});

test('addLine rejects invalid quantity', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'UNKNOWN-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine removes a line from the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const r2 = removeLine(r1.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const originalLength = r1.value.lines.length;
  removeLine(r1.value, 'DES-HOUR');
  assert.equal(r1.value.lines.length, originalLength);
});

test('removeLine reports line not found', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'UNKNOWN-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21 },
    ],
  };
  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice assigns number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
});

test('issueInvoice uses next number based on existing', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const existingNumbers = ['INV-2026-0001', 'INV-2026-0005'];
  const r2 = issueInvoice(r.value, existingNumbers);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0006');
});

test('issueInvoice does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const originalStatus = r.value.status;
  issueInvoice(r.value, []);
  assert.equal(r.value.status, originalStatus);
  assert.equal(r.value.number, undefined);
});

test('issueInvoice preserves all invoice data', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2026-10-07');
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('issueInvoice rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice rejects invalid discount percent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 150 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects negative discount percent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -5 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects non-numeric discount percent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('lineDiscount returns 0 for no discount', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount calculates discount correctly', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10 };
  assert.equal(lineDiscount(line), 10000);
});

test('lineDiscount rounds to nearest cent', () => {
  const line = { qty: 3, unitPrice: 100, discountPercent: 33.33 };
  const discount = lineDiscount(line);
  assert.ok(Number.isInteger(discount));
});

test('lineDiscount clamps to 0', () => {
  const line = { qty: 1, unitPrice: 50, discountPercent: 0 };
  assert.equal(lineDiscount(line), 0);
});

test('invoiceTotals returns discount and VAT summary', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 4250);
  assert.ok(totals.vat > 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.discount, (5 * 8500 * 10) / 100 + (10 * 9500 * 20) / 100);
  assert.ok(totals.total > 0);
});

test('invoiceTotals clamps total to 0', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, vatRate: 0, discountPercent: 200 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(totals.total >= 0);
});

test('addLine accepts discountPercent', () => {
