    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(r2.ok, true);
